// Finite probes compare observed Node and guest behavior before stream cleanup.
export const compressionLifecycleProbe =
	"const outcome = (kind, value) => ({kind, ...(kind === 'rejected' ? {type:typeof value,name:value?.name??null,code:value?.code??null,message:typeof value==='string'?value:String(value?.message??value).slice(0,160)} : value && typeof value.done==='boolean' ? {done:value.done,valueBytes:value.value?.byteLength??null} : {})});\nasync function settle(p) { let timer; try { return await Promise.race([Promise.resolve(p).then(v=>outcome('fulfilled',v),e=>outcome('rejected',e)),new Promise(r=>{timer=setTimeout(()=>r({kind:'pending'}),100);})]); } finally {clearTimeout(timer);} }\nconst rows=[];\nfor(const name of ['CompressionStream','DecompressionStream']) {\n for(const direction of ['cancel-readable','abort-writable']) {\n  for(const reasonKind of ['undefined','error']) {\n   const pair=new globalThis[name]('gzip');const reader=pair.readable.getReader();const writer=pair.writable.getWriter();\n   const reason=reasonKind==='error'?new Error('stream-stop'):undefined;\n   const readerClosed=reader.closed.then(v=>outcome('fulfilled',v),e=>outcome('rejected',e));\n   const writerClosed=writer.closed.then(v=>outcome('fulfilled',v),e=>outcome('rejected',e));\n   const read=reader.read().then(v=>outcome('fulfilled',v),e=>outcome('rejected',e));\n   const action=direction==='cancel-readable'?reader.cancel(reason):writer.abort(reason);\n   const actionResult=await settle(action);\n   let timer;const observe=async p=>{try{return await Promise.race([p,new Promise(r=>{timer=setTimeout(()=>r({kind:'pending'}),100);})]);}finally{clearTimeout(timer);}};\n   const beforeCleanup={reader:await observe(readerClosed),writer:await observe(writerClosed),read:await observe(read)};\n   const cleanup=[await settle(reader.cancel()),await settle(writer.abort())];\n   const release=[];for(const endpoint of [reader,writer]){try{endpoint.releaseLock();release.push('released');}catch(e){release.push({name:e.name,code:e.code??null});}}\n   rows.push({name,direction,reasonKind,action:actionResult,beforeCleanup,cleanup,release});\n  }\n }\n}\nconsole.log(JSON.stringify(rows));";
export const crossRealmCryptoProbe =
	"import vm from 'node:vm';import {timingSafeEqual} from 'node:crypto';\nconst other=vm.runInNewContext('({buffer:new Uint8Array([1,2]).buffer,view:new Uint8Array([1,2]),shared:typeof SharedArrayBuffer===\"undefined\"?null:new SharedArrayBuffer(2)})');\nconst rows=[];for(const [name,value]of Object.entries(other)){if(value===null){rows.push({name,available:false});continue;}const expected=name==='shared'?new Uint8Array(2):new Uint8Array([1,2]);try{rows.push({name,available:true,sameRealmArrayBuffer:value instanceof ArrayBuffer,isView:ArrayBuffer.isView(value),result:timingSafeEqual(value,expected)});}catch(e){rows.push({name,available:true,error:{name:e.name,code:e.code??null,message:String(e.message).slice(0,160)}});}}\nconsole.log(JSON.stringify(rows));";
